package com.termux.app.workspace;
import android.app.*;import android.os.Looper;import android.widget.Button;import android.view.View;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.BooleanSupplier;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class,instrumentedPackages={"com.termux.app.workspace.ImageGalleryExport"},shadows=ImageGalleryUiTest.Exporter.class)
public class ImageGalleryUiTest {
 static AtomicInteger saves=new AtomicInteger();static byte[] copied;static String originalName,failure="";TermuxActivity activity;ChatAttachmentUi ui;
 @Implements(value=ImageGalleryExport.class,isInAndroidSdk=false)
 public static class Exporter {@Implementation protected static ImageGalleryExport.Result save(android.content.Context c,File original,String name,BooleanSupplier cancelled)throws IOException{assertFalse(cancelled.getAsBoolean());saves.incrementAndGet();copied=java.nio.file.Files.readAllBytes(original.toPath());originalName=name;if(!failure.isEmpty())throw new ImageGalleryExport.Failure(failure,null);return new ImageGalleryExport.Result(android.net.Uri.parse("content://fixture/images/"+saves.get()),name);}}
 static ChatAttachmentUi.ZoomImage zoom(View root){if(root instanceof ChatAttachmentUi.ZoomImage)return (ChatAttachmentUi.ZoomImage)root;if(root instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)root;for(int i=0;i<group.getChildCount();i++){ChatAttachmentUi.ZoomImage found=zoom(group.getChildAt(i));if(found!=null)return found;}}return null;}
 void idle()throws Exception{Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 void await(Button button)throws Exception{for(int n=0;n<200&&!button.isEnabled();n++)idle();assertTrue(button.isEnabled());}
 void check(String agent)throws Exception{for(boolean agentFile:new boolean[]{false,true})for(boolean gif:new boolean[]{false,true}){
  saves.set(0);failure="";copied=null;activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.setTheme(R.style.Theme_Termux_Black);WorkspaceLanguage.select(activity,agentFile?"en":"ru");WorkspaceLanguage.apply(activity);Shadows.shadowOf(RuntimeEnvironment.application).grantPermissions(android.Manifest.permission.WRITE_EXTERNAL_STORAGE);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";AgentChatView view=new AgentChatView(activity,row->fail("No model turn"),()->{},()->{},()->{},()->{});ui=new ChatAttachmentUi(activity,view);File dir=new File(ChatAttachments.root(activity,p),"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");assertTrue(dir.isDirectory()||dir.mkdirs());File original=new File(dir,gif?"original.gif":"original.png");if(gif)java.nio.file.Files.write(original.toPath(),ImageGalleryExportTest.gif());else{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(1,1,android.graphics.Bitmap.Config.ARGB_8888);try(OutputStream out=new FileOutputStream(original)){assertTrue(bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}bitmap.recycle();}byte[] before=java.nio.file.Files.readAllBytes(original.toPath());String path=ChatAttachments.prefix(p)+dir.getName()+"/"+original.getName(),name=original.getName();ui.sync("fixture",p,true);
  try{assertFalse(ui.has());if(agentFile)ui.capturePath(path).run();else ui.captureAttachment(new JSONObject().put("name",name).put("type","image").put("path",path)).run();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();Button gallery=dialog.getButton(AlertDialog.BUTTON_NEUTRAL),download=dialog.getButton(AlertDialog.BUTTON_POSITIVE);assertNotNull(gallery);assertEquals(agentFile?"To gallery":"В галерею",gallery.getText().toString());await(gallery);assertTrue(download.isEnabled());View decor=dialog.getWindow().getDecorView();if(!gif){ChatAttachmentUi.ZoomImage image=zoom(decor);assertNotNull("The original must render, not merely enable Save",image);assertNotNull(image.getDrawable());}decor.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1000,View.MeasureSpec.AT_MOST));decor.layout(0,0,320,decor.getMeasuredHeight());assertTrue("Gallery is on the left of Download",gallery.getLeft()<download.getLeft());for(int n=1;n<=2;n++){gallery.performClick();await(gallery);assertEquals(n,saves.get());assertEquals(name,originalName);assertArrayEquals(before,copied);assertTrue(ShadowToast.getTextOfLatestToast().contains("Pictures/TermuxJobs/"));assertFalse(ui.has());}failure="UNSUPPORTED_IMAGE";gallery.performClick();await(gallery);String toast=ShadowToast.getTextOfLatestToast();assertTrue(toast.contains("формат")||toast.contains("format"));assertFalse(toast.startsWith("Saved:")||toast.startsWith("Сохранено:"));assertTrue(download.isEnabled());assertFalse(ui.has());assertArrayEquals(before,java.nio.file.Files.readAllBytes(original.toPath()));java.lang.reflect.Field broad=TermuxActivity.class.getDeclaredField("mWorkspaceStorageAccess");broad.setAccessible(true);assertNull("Gallery must not use the general all-files permission path",broad.get(activity));assertNull(Shadows.shadowOf(activity).getLastRequestedPermission());dialog.dismiss();
  }finally{ui.close();ui=null;activity.finish();activity=null;}
 }}
 @After public void end(){if(ui!=null)ui.close();if(activity!=null)activity.finish();}
 @Test public void codexUserAndAgentPngGifSaveOriginalWithoutModelInput()throws Exception{check("codex");}
 @Test public void claudeUserAndAgentPngGifSaveOriginalWithoutModelInput()throws Exception{check("claude");}
 @Test public void geminiUserAndAgentPngGifSaveOriginalWithoutModelInput()throws Exception{check("gemini");}
 @Test public void openCodeUserAndAgentPngGifSaveOriginalWithoutModelInput()throws Exception{check("opencode");}
}
